package com.bank.wildcard;

import java.util.logging.Logger;

// Validates flexible grouping templates for National Bank of India.
public class WildcardValidator {
    private static final Logger log = Logger.getLogger(WildcardValidator.class.getName());

    // '*' = '(' or ')' or empty. Greedy open-count range. O(n), O(1).
    public boolean canBeValid(String template) {
        if (template == null) {
            throw new IllegalArgumentException("template must not be null");
        }
        int low = 0;    // minimum possible open brackets
        int high = 0;   // maximum possible open brackets
        for (char c : template.toCharArray()) {
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                low--;
                high--;
            } else {            // '*': could be ')' (low--), '(' (high++), or empty
                low--;
                high++;
            }
            if (high < 0) {     // even optimistically too many closers
                log.info(() -> "'" + template + "' CANNOT be valid");
                return false;
            }
            if (low < 0) {
                low = 0;        // never fewer than zero open; treat extras as empty
            }
        }
        boolean ok = low == 0;  // zero open achievable at the end
        log.info(() -> "'" + template + "' " + (ok ? "CAN" : "CANNOT") + " be valid");
        return ok;
    }
}
