package com.bank.wildcard;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: validate flexible grouping templates.
public class WildcardValidatorDemo {
    private static final Logger log = Logger.getLogger(WildcardValidatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        WildcardValidator validator = new WildcardValidator();

        log.info(() -> "Result = " + validator.canBeValid("(*)"));   // true
        log.info(() -> "Result = " + validator.canBeValid("(*))"));  // true
        log.info(() -> "Result = " + validator.canBeValid(")("));    // false
    }
}
